def set_operations(a, b):
    union = a.copy()
    for x in b:
        if x not in union:
            union.append(x)
    intersection = []
    for x in a:
        if x in b:
            intersection.append(x)
    difference = []
    for x in a:
        if x not in b:
            difference.append(x)
    return {'union': union, 'intersection': intersection, 'difference': difference}

