def incremental_compile(project):
    import os
    cache = '.duan_cache'
    if not os.path.exists(cache):
        os.makedirs(cache)
    for f in os.listdir(project):
        if f.endswith('.duan'):
            src_path = os.path.join(project, f)
            cache_path = os.path.join(cache, f + '.llvm')
            if os.path.exists(cache_path):
                src_mtime = os.path.getmtime(src_path)
                cache_mtime = os.path.getmtime(cache_path)
                if cache_mtime >= src_mtime:
                    print(f'Skipping {f}, up to date')
                    continue
            print(f'Compiling {f}...')
            compile_file(src_path, cache_path)

