def matrix_operations(matrix):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    transposed = []
    for j in range(cols):
        new_row = []
        for i in range(rows):
            new_row.append(matrix[i][j])
        transposed.append(new_row)
    row_sums = []
    for i in range(rows):
        s = 0
        for j in range(cols):
            s += matrix[i][j]
        row_sums.append(s)
    return {'transposed': transposed, 'row_sums': row_sums, 'rows': rows, 'cols': cols}

