class Fibonacci:
    def __init__(self, max_count):
        self.max_count = max_count
        self.count = 0
        self.a = 0
        self.b = 1
    def __iter__(self):
        return self
    def __next__(self):
        if self.count >= self.max_count:
            raise StopIteration()
        if self.count == 0:
            self.count += 1
            return 0
        if self.count == 1:
            self.count += 1
            return 1
        result = self.a + self.b
        self.a = self.b
        self.b = result
        self.count += 1
        return result

class TodoList:
    def __init__(self):
        self.todos = []
        self.counter = 0
    def add(self, title, priority='medium'):
        self.counter += 1
        self.todos.append({'id': self.counter, 'title': title, 'priority': priority, 'done': False})
        return self.counter
    def complete(self, todo_id):
        for todo in self.todos:
            if todo['id'] == todo_id:
                todo['done'] = True
                return True
        return False
    def list_by_priority(self, priority):
        result = []
        for todo in self.todos:
            if todo['priority'] == priority and not todo['done']:
                result.append(todo)
        return result
    def stats(self):
        total = len(self.todos)
        done = sum(1 for t in self.todos if t['done'])
        pending = total - done
        return {'total': total, 'done': done, 'pending': pending}

