def word_frequency_analysis(text):
    words = text.split()
    freq = {}
    for w in words:
        w = w.lower().strip('.,!?;:()[]{}""')
        if w:
            freq[w] = freq.get(w, 0) + 1
    sorted_words = sorted(freq.items(), key=lambda x: (-x[1], x[0]))
    top_n = sorted_words[:10]
    total_words = len(words)
    unique_words = len(freq)
    result = {
        'total': total_words,
        'unique': unique_words,
        'top_10': top_n,
        'freq': freq
    }
